    prompt = f"""Classify the following question into exactly one of these categories:
- "coder": programming, code, error, debug, script related
- "bonsai": short greeting, simple question, casual conversation
- "groq": complex explanation, comparison, analysis, long answer needed

Question: {question}

Reply with only one word (coder/bonsai/groq):"""

    result = call_openrouter(
        MODEL_CLASSIFY,
        [{"role": "user", "content": prompt}],
        max_tokens=10,
        temperature=0
    )
    result = result.strip().lower()
    if "coder" in result:
        return "coder"
    elif "bonsai" in result:
        return "bonsai"
    return "groq"


